import type { APIRoute } from 'astro';
import { SITE_URL, LICENSE_URL } from '../../lib/jsonld';
import { CHANGELOG_FEED_PATH } from '../../lib/changelog';
import { mirroredLanguages } from '../../lib/markdown';

// RFC 9727 API catalog: a linkset listing the machine-readable endpoints this
// site already publishes, so an agent can discover them from one well-known
// URL instead of scraping HTML. Every entry is a static file generated by
// this build — there is no live API — and `npm run check:routes` fails if
// any href here has no file behind it.
//
// Served as application/linkset+json via public/_headers (the file has no
// extension, so Pages would otherwise guess application/octet-stream).
//
// Per-language reader bundles are listed for the same set of languages that
// get one (src/pages/l/[code]/stories.json.ts builds exactly
// mirroredLanguages()), so this cannot name a bundle that was not built.
const abs = (path: string) => `${SITE_URL}${path}`;

export const GET: APIRoute = () => {
  const items = [
    { href: abs('/ai/summary.json'), type: 'application/json', title: 'Site summary' },
    { href: abs('/llms.txt'), type: 'text/plain', title: 'Index of languages and markdown mirrors' },
    { href: abs('/llms-full.txt'), type: 'text/plain', title: 'Full site text for language models' },
    { href: abs(CHANGELOG_FEED_PATH), type: 'application/atom+xml', title: 'Newly published and updated languages' },
    { href: abs('/sitemap-index.xml'), type: 'application/xml', title: 'Sitemap index' },
    ...mirroredLanguages().map((lang) => ({
      href: abs(`/l/${encodeURIComponent(lang.code)}/stories.json`),
      type: 'application/json',
      // RFC 9264 §4.2.4.1: hreflang is always an array in a JSON linkset.
      hreflang: [lang.code],
    })),
  ];

  const body = {
    linkset: [
      {
        anchor: abs('/.well-known/api-catalog'),
        item: items,
        'service-doc': [{ href: abs('/llms.txt'), type: 'text/plain' }],
        license: [{ href: LICENSE_URL }],
      },
    ],
  };

  return new Response(JSON.stringify(body, null, 2), {
    headers: { 'Content-Type': 'application/linkset+json; profile="https://www.rfc-editor.org/info/rfc9727"' },
  });
};
